import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp, writeFile, rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';

async function scenario(fn) {
  const server = await testServer();
  const directory = await mkdtemp(tmpdir() + '/crew-search-cli-');
  try {
    const api = server.agent();
    await api('POST', '/auth/signup', {name: 'Search CLI', email: 'searchcli@example.test', password: 'correct-horse-battery'});
    const org = (await api('POST', '/orgs', {name: 'CLI search'})).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'CLI', name: 'CLI search project'})).data.project;
    const token = (await api('POST', '/tokens', {name: 'CLI', scopes: ['*']})).data.token;
    await writeFile(directory + '/config.json', JSON.stringify({url: server.url, token}), {mode: 0o600});
    const cli = args => new Promise((resolve, reject) => {
      const child = spawn(process.execPath, [fileURLToPath(new URL('../bin/crew.js', import.meta.url)), ...args, '--config', directory + '/config.json', '--json']);
      let stdout = '', stderr = '';
      const timer = setTimeout(() => {child.kill('SIGKILL'); reject(new Error('CLI deadline exceeded'));}, 10000);
      child.stdout.on('data', value => stdout += value);
      child.stderr.on('data', value => stderr += value);
      child.on('error', error => {clearTimeout(timer); reject(error);});
      child.on('close', code => {
        clearTimeout(timer);
        let data = null;
        try {if (stdout.trim()) data = /^[{[]/.test(stdout.trim()) ? JSON.parse(stdout) : stdout.trim();} catch (error) {reject(error); return;}
        resolve({code, data, stdout, stderr});
      });
    });
    await fn({api, org, project, cli, directory});
  } finally {await server.close(); await rm(directory, {recursive: true, force: true});}
}

test('actual token CLI searches compound queries and traverses all cursor pages', () => scenario(async ({api, org, project, cli}) => {
  for (const title of ['Search first', 'Search second', 'Search third']) await api('POST', '/projects/' + project.id + '/issues', {title, priority: 3});
  const result = await cli(['search', '--org', org.id, '--query', 'search AND priority>=3', '--limit', '1', '--all']);
  assert.equal(result.code, 0, result.stderr);
  assert.equal(result.data.items.length, 3);
  assert.equal(result.data.nextCursor, null);
}));
test('actual CLI validates queries locally and gets accessible suggestions', () => scenario(async ({cli, org}) => {
  const checked = await cli(['search', 'check', 'assignee:@me AND NOT status:done']);
  assert.equal(checked.code, 0, checked.stderr); assert.equal(checked.data.valid, true);
  assert.equal((await cli(['search', 'check', 'label:'])).code, 1);
  const suggestions = await cli(['search', 'suggest', 'project:', '--org', org.id]);
  assert.equal(suggestions.code, 0, suggestions.stderr);
  assert.equal(suggestions.data.items[0].replacement, 'project:CLI');
}));
test('actual CLI creates edits runs and confirms deletion of saved filters', () => scenario(async ({api, cli, org, project, directory}) => {
  await api('POST', '/projects/' + project.id + '/issues', {title: 'Important', priority: 4});
  await writeFile(directory + '/query.txt', 'priority>=3');
  const created = await cli(['filter', 'create', '--org', org.id, '--name', 'Urgent', '--query-file', directory + '/query.txt']);
  assert.equal(created.code, 0, created.stderr);
  const id = created.data.filter.id;
  assert.equal((await cli(['filter', 'run', id])).data.total, 1);
  const edited = await cli(['filter', 'edit', id, '--name', 'Critical', '--query', 'priority>=4', '--revision', '1']);
  assert.equal(edited.code, 0, edited.stderr); assert.equal(edited.data.filter.revision, 2);
  assert.equal((await cli(['filter', 'edit', id, '--name', 'Stale', '--revision', '1'])).code, 1);
  assert.equal((await cli(['filter', 'delete', id])).code, 1);
  assert.equal((await cli(['filter', 'delete', id, '--yes'])).code, 0);
  assert.equal((await cli(['filter', 'show', id])).code, 1);
}));
test('actual CLI lists saved filters and documents every search family', () => scenario(async ({cli, org}) => {
  await cli(['filter', 'create', '--org', org.id, '--name', 'Everything']);
  const list = await cli(['filter', 'list', '--org', org.id]);
  assert.equal(list.code, 0, list.stderr); assert.equal(list.data.items[0].name, 'Everything');
  const options = await cli(['filter', 'options', '--org', org.id]);
  assert.equal(options.code, 0, options.stderr); assert.equal(options.data.projects.length, 1);
  assert.equal((await cli(['search', '--help'])).code, 0);
  assert.equal((await cli(['filter', '--help'])).code, 0);
}));
